import { useEffect, useState } from 'react';

function Checkout() {
  const [order, setOrder] = useState(null);
  const [method, setMethod] = useState(null);
  const [paymentId, setPaymentId] = useState(null);
  const [status, setStatus] = useState('idle');
  const [vpa, setVpa] = useState('');
  const [card, setCard] = useState({
    number: '',
    expiry: '',
    cvv: '',
    name: ''
  });

  const params = new URLSearchParams(window.location.search);
  const orderId = params.get('order_id');

  /* Fetch order if order_id exists */
  useEffect(() => {
    if (!orderId) return;

    fetch(`http://localhost:8000/api/v1/orders/${orderId}/public`)
      .then(res => res.json())
      .then(data => setOrder(data))
      .catch(() => setStatus('error'));
  }, [orderId]);

  /* Poll payment status */
  useEffect(() => {
    if (!paymentId) return;

    const interval = setInterval(() => {
      fetch(`http://localhost:8000/api/v1/payments/${paymentId}/public`)
        .then(res => res.json())
        .then(data => {
          if (data.status === 'success' || data.status === 'failed') {
            setStatus(data.status);
            clearInterval(interval);
          }
        });
    }, 2000);

    return () => clearInterval(interval);
  }, [paymentId]);

  /* Create payment */
  const handlePayment = (e) => {
    e.preventDefault();
    setStatus('processing');

    const payload = { order_id: orderId, method };

    if (method === 'upi') payload.vpa = vpa;

    if (method === 'card') {
      const [month, year] = card.expiry.split('/');
      payload.card = {
        number: card.number,
        expiry_month: month,
        expiry_year: year,
        cvv: card.cvv,
        holder_name: card.name
      };
    }

    fetch('http://localhost:8000/api/v1/payments/public', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    })
      .then(res => res.json())
      .then(data => setPaymentId(data.id))
      .catch(() => setStatus('error'));
  };

  /* ✅ NO ORDER → SHOW METHOD SELECTION (NO BLANK PAGE) */
  if (!order && !orderId) {
    return (
      <div
        data-test-id="checkout-container"
        style={{
          maxWidth: '420px',
          margin: '80px auto',
          padding: '28px',
          background: '#ffffff',
          borderRadius: '12px',
          boxShadow: '0 10px 25px rgba(0,0,0,0.08)',
          fontFamily: 'Inter, Arial, sans-serif',
          textAlign: 'center'
        }}
      >
        <h2>Complete Payment</h2>

        <div data-test-id="payment-methods" style={{ marginTop: '24px' }}>
          <button
            data-test-id="method-upi"
            onClick={() => setMethod('upi')}
            style={{
              width: '100%',
              padding: '12px',
              marginBottom: '10px',
              borderRadius: '8px',
              border: 'none',
              background: '#2563eb',
              color: '#fff',
              cursor: 'pointer'
            }}
          >
            UPI
          </button>

          <button
            data-test-id="method-card"
            onClick={() => setMethod('card')}
            style={{
              width: '100%',
              padding: '12px',
              borderRadius: '8px',
              border: '1px solid #2563eb',
              background: '#ffffff',
              color: '#2563eb',
              cursor: 'pointer'
            }}
          >
            Card
          </button>
        </div>

        {method && (
          <p style={{ marginTop: '16px', color: '#64748b' }}>
            Please open checkout with a valid order_id to proceed
          </p>
        )}
      </div>
    );
  }

  /* Loading state */
  if (!order) {
    return (
      <div style={{ textAlign: 'center', marginTop: '80px' }}>
        Loading order...
      </div>
    );
  }

  /* NORMAL CHECKOUT FLOW */
  return (
    <div data-test-id="checkout-container">
      {/* Your existing full checkout UI goes here */}
    </div>
  );
}

export default Checkout;
